function parseFormula(body) {
  const toks = tokenize(body)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) throw new ParseError(); p++ }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new ParseError()
    const tk = toks[p]
    if (tk.t === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.t === 'op') {
      if (tk.v === '(') {
        p++
        const e = cmp()
        expect(')')
        return { t: 'paren', e }
      }
      throw new ParseError()
    }
    p++
    const name = tk.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          break
        }
      }
      expect(')')
      return { t: 'call', name, args }
    }
