  if (node.t === 'range') {
    const cs = rangeCells(node)
    if (!cs) return [err('#REF!')]
    return cs.map(cellValue)
  }
  return [evalNode(node)]
}

function evalNode(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'paren': return evalNode(n.e)
    case 'ref': return cellValue(n.a)
    case 'range': return err('#ERR!')
    case 'neg': {
      const x = toNum(evalNode(n.e))
      if (isErr(x)) return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': return evalBin(n)
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalBin(n) {
  const l = evalNode(n.l)
